package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

/** Actual pending policy, original private facts/witnesses, publication/refusal and exact reopen. */
public final class ContextPrivateWitnessWriteRunner {
    static int checks;static final int WORK=64000000;
    static final String BUNDLE="!$w seed(w,1)&&flag(w,1);",MID="!@w seed(w,1)&&gate(1)->mid(w,1);",DONE="!@w mid(w,1)->done(w,1);",OUT="!@w done(w,1)->out(w,1);",NEG="!@w done(w,1)->~flag(w,1);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static void command(ContextAutomaticPendingCommitRunner.Fixture f,String s)throws Exception{ContextTrustedProductionCommitRunner.command(f,s);}
    static ContextProductionInventory inventory(ContextAutomaticPendingCommitRunner.Fixture f)throws Exception{return ContextTrustedProductionCommitRunner.inventory(f);}
    static void proof(ContextProductionFamilyAssembly.Evaluation e,boolean conflict,boolean grouped,Map<UUID,ContextProductionInventory> members,long revision,long mid){
        require(e.status==(conflict?ContextProductionFamilyAssembly.Status.COLLISION:ContextProductionFamilyAssembly.Status.FIXED_POINT),"complete actual private witness verdict: "+e.reason);
        if(!conflict){require(e.refutations.isEmpty(),"safe result has no invented collision");return;}
        require(e.barrier==(grouped?1:2)&&!e.refutations.isEmpty(),"grouped local chain or independent next-round chain reaches the exact refutation barrier");Set<Source> expected=new HashSet<>();for(ContextProductionInventory member:members.values())for(ContextProductionInventory.Row row:member.primary)expected.add(new Source(member.context,member.revision,row.nativeRule,false,"inventory:"+member.fingerprint));
        for(ContextProductionFamilyAssembly.Refutation r:e.refutations){require(r.producer.localX&&r.producer.revision==revision&&r.producer.rule!=mid,"whole pending negative X rule refutes");for(Support p:r.proofs){Set<Source> foreign=new HashSet<>();Set<Long> local=new HashSet<>();for(Source s:p.sources)if(s.localX){require(s.revision==revision&&s.view.equals(r.producer.view),"one exact pending X view, no irrelevant anchor");local.add(s.rule);}else foreign.add(s);require(foreign.equals(expected)&&local.equals(new HashSet<>(Arrays.asList(mid,r.producer.rule)))&&p.depth==3&&p.sources.size()==5,"original A bundle+A gate+B producer and exact two X Sources, depth3");}}
    }
    static void one(boolean grouped,boolean reverse,boolean conflict)throws Exception{
        Path dir=Files.createTempDirectory("private-witness-write-");System.setProperty("user.home",dir.toString());boolean initialized=reverse;ContextSevenPremiseNativeWriteRunner.create(dir,"A",BUNDLE+(initialized?"":" !gate(1);"));ContextSevenPremiseNativeWriteRunner.create(dir,"B",DONE);Set<String> settled;List<RevisionRef> pins=new ArrayList<>();Map<UUID,String> foreign;long after;
        try(ContextAutomaticPendingCommitRunner.Fixture f=new ContextAutomaticPendingCommitRunner.Fixture(dir,"X")){
            require(f.root.compile("!anchor(1); "+MID,null,false),"X has no private witness/fact primary");for(String name:reverse?new String[]{"B","A"}:new String[]{"A","B"})command(f,"ctx connect "+name+(grouped?" trust own":""));if(initialized)command(f,"ctx ask A !gate(1);");f.db.saveConnections(f.root);ContextProductionInventory before=inventory(f);long revision=f.db.getRevision(),mid=before.primary.stream().filter(r->r.origin.equals(MID)).findFirst().get().nativeRule;Map<UUID,ContextProductionInventory> members=new HashMap<>();for(ContextConnection c:f.db.dmzTopology()){pins.add(c.getTarget());members.put(c.getTarget().getContextId(),ContextProductionInventory.inspect(c.layer(),c.getTarget().getContextId(),c.getTarget().getRevision(),false,c.getInitialization(),1000));}require(members.values().stream().anyMatch(i->!i.initialization.isEmpty())==initialized,"diagnostic includes exact initialized private view");foreign=ContextTrustedProductionCommitRunner.foreign(f);String candidate=conflict?NEG:OUT;
            ContextPendingProductionSnapshotSession.Decision diagnostic;Mind child=new Mind(f.root);require(child.compile(candidate,null,false),"exact proposed child");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){diagnostic=lease.inspectAutomatic(16,16,16,65536,1000000,WORK,500000,WORK,WORK,100000);require(diagnostic.engine==ContextPendingProductionSnapshotSession.Engine.WITNESS,"private primary selects witness engine");proof(diagnostic.witness,conflict,grouped,members,revision,mid);lease.requireCurrent();}finally{f.root.release(child);}
            require(inventory(f).fingerprint.equals(before.fingerprint)&&f.db.getRevision()==revision,"detached diagnostic leaves source/revision unchanged");
            f.guard.install();StorageLifecycleException failure=null;try{require(Boolean.TRUE.equals(f.root.query(candidate,null,false)),"actual safe private witness write");}catch(StorageLifecycleException e){failure=e;}finally{f.guard.restore();}
            require((failure!=null)==conflict,"actual publication/refusal matches fresh diagnostic");if(conflict){require(failure instanceof ContextWitnessProductionCommitException&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT,"typed original-source private witness refusal");ContextProductionFamilyAssembly.Evaluation actual=((ContextWitnessProductionCommitException)failure).getFamilyEvaluation();require(actual!=diagnostic.witness,"historical detached verdict cannot be reused as commit authority");proof(actual,true,grouped,members,revision,mid);require(f.db.getRevision()==revision&&inventory(f).fingerprint.equals(before.fingerprint),"collision preserves exact source fingerprint and revision");}else require(f.db.getRevision()>revision,"safe publication advances revision");
            settled=ContextSevenPremiseNativeWriteRunner.origins(inventory(f));require(settled.equals(new HashSet<>(conflict?Arrays.asList("!anchor(1);",MID):Arrays.asList("!anchor(1);",MID,candidate))),"only whole candidate published, no raw private gate/seed/flag or derived facts become primaries");require(ContextTrustedProductionCommitRunner.foreign(f).equals(foreign),"initialized original member inventories unchanged by diagnostic/write");after=f.db.getRevision();
        }
        try(ContextAutomaticPendingCommitRunner.Fixture f=new ContextAutomaticPendingCommitRunner.Fixture(dir,"X")){require(f.db.getRevision()>=after&&ContextSevenPremiseNativeWriteRunner.origins(inventory(f)).equals(settled),"ordinary reopen preserves exact accepted/refused primary set");List<RevisionRef> actual=new ArrayList<>();for(ContextConnection c:f.db.dmzTopology())actual.add(c.getTarget());require(actual.equals(pins),"ordinary reopen preserves member pins/order");require(ContextTrustedProductionCommitRunner.foreign(f).equals(foreign),"ordinary reopen preserves initialized private member views");}
    }
    static void stale()throws Exception{
        Path dir=Files.createTempDirectory("private-witness-stale-");System.setProperty("user.home",dir.toString());ContextSevenPremiseNativeWriteRunner.create(dir,"A",BUNDLE+" !gate(1);");ContextSevenPremiseNativeWriteRunner.create(dir,"B",DONE);
        try(ContextAutomaticPendingCommitRunner.Fixture f=new ContextAutomaticPendingCommitRunner.Fixture(dir,"X")){
            require(f.root.compile("!anchor(1); "+MID,null,false),"stale witness lease baseline");command(f,"ctx connect A trust own");command(f,"ctx connect B trust own");f.db.saveConnections(f.root);long revision=f.db.getRevision();String before=inventory(f).fingerprint;command(f,"transaction start");Mind child=(Mind)f.user.getCurrentMind();require(child.query(OUT,null,false),"actual pending user child");
            try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){ContextPendingProductionSnapshotSession.Decision d=lease.inspectAutomatic(16,16,16,65536,1000000,WORK,500000,WORK,WORK,100000);require(d.engine==ContextPendingProductionSnapshotSession.Engine.WITNESS&&d.witness.status==ContextProductionFamilyAssembly.Status.FIXED_POINT,"fresh complete private witness diagnostic");command(f,"ctx ask A !extra(1);");boolean stopped=false;try{lease.inspectAutomatic(16,16,16,65536,1000000,WORK,500000,WORK,WORK,100000);}catch(IllegalStateException e){stopped=true;}require(stopped,"changed private initialized member invalidates old lease before verdict reuse");}
            command(f,"transaction rollback");require(f.user.getCurrentMind()==f.root&&f.db.getRevision()==revision&&inventory(f).fingerprint.equals(before),"rollback restores exact source after stale diagnostic");require(f.db.dmzTopology().stream().allMatch(c->c.getInitialization().isEmpty()),"rollback restores original empty initialization");
        }
    }
    public static void main(String[] args){try{for(boolean g:new boolean[]{false,true})for(boolean r:new boolean[]{false,true})for(boolean c:new boolean[]{false,true})one(g,r,c);stale();System.out.println("CONTEXT_PRIVATE_WITNESS_WRITE_PASS checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
